use std::{cell::RefCell, rc::Rc};

pub struct Select { pub value: Option<String> }   // one owner, no ambient scope
pub struct OptionHandle(Rc<RefCell<Select>>);     // explicit, bounded hand-off

impl OptionHandle {
    pub fn select(&self, v: &str) {               // runtime-checked borrow
        self.0.borrow_mut().value = Some(v.to_owned());
    }
}
